unitsize(0.6 cm);

pair A, B, C, E, P;

A = (2,5);
B = (0,0);
C = (6,0);
P = (A + 2*B + 3*C)/6;
E = extension(B,P,A,C);

draw(A--B--C--cycle);
draw(A--P);
draw(B--P);
draw(C--P);
draw(P--E);

label("$A$", A, N);
label("$B$", B, SW);
label("$C$", C, SE);
label("$E$", E, NE);
label("$P$", P, S);
[/asy]

